completedCommands.command:
node <<'NODE'
'use strict';
var assert = require('assert');
var Denque = require('./');

var seen = [];
var queue = new Denque([0, 'keep', false, 'remove']);
assert.strictEqual(queue.removeWhere(function (value, index) {
  seen.push([value, index]);
  return value === 0 || value === false || value === 'remove';
}), 3);
assert.deepStrictEqual(seen, [[0, 0], ['keep', 1], [false, 2], ['remove', 3]]);
assert.deepStrictEqual(queue.toArray(), ['keep']);

queue = new Denque([1, 2, 3]);
var original = queue.toArray();
var error = new Error('stop');
assert.throws(function () {
  queue.removeWhere(function (value, index) {
    if (index === 0) return true;
    throw error;
  });
}, function (thrown) { return thrown === error; });
assert.strictEqual(queue.peekAt(0), original[0]);
assert.strictEqual(queue.peekAt(1), original[1]);
assert.strictEqual(queue.peekAt(2), original[2]);
assert.throws(function () { new Denque().removeWhere(null); }, Error);

queue = new Denque([0, 'same', false, 'same'], { capacity: 4 });
queue.shift();
queue.push(0);
var capacity = queue._list.length;
assert.strictEqual(queue.removeWhere(function (value) { return !value; }), 2);
assert.strictEqual(queue.peekAt(0), queue.peekAt(1));
assert.strictEqual(queue._list.length, capacity);
queue.push('tail');
queue.unshift('head');
assert.deepStrictEqual(queue.toArray(), ['head', 'same', 'same', 'tail']);
NODE

